sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_backLayers;
uniform float amzp_frontLayers;
uniform float amzp_spaceMode;
uniform float amzp_depth;
uniform float amzp_layerGap;
uniform float amzp_startGap;
uniform float amzp_endScale;
uniform float amzp_twist;
uniform float2 amzp_endOff;
uniform float amzp_sideShade;
layout(color) uniform half4 amzp_nearCol;
layout(color) uniform half4 amzp_farCol;
uniform float amzp_colorMix;
uniform float amzp_endOpacity;
uniform float amzp_keepFace;
uniform float amzp_hideFace;
uniform float amzp_camSrc;
uniform float amzp_flatAngle;
uniform float amzp_flatLen;
uniform float amzp_overdrawOn;
    uniform float4x4 nmModel;
    uniform float4x4 nmView;
    uniform float4x4 nmProj;
    bool SCN;
    float3 MO, MX, MY, MZ;
    float3x3 MI;
    float GPS;
    float camOK() { return (nmProj[2][3] > 0.5 && abs(nmProj[0][0]) + abs(nmProj[1][1]) > 1e-6) ? 1.0 : 0.0; }
    float3 rayDir(float2 q) {
        float3 r0 = float3(nmProj[0][0], nmProj[1][0], nmProj[2][0]);
        float3 r1 = float3(nmProj[0][1], nmProj[1][1], nmProj[2][1]);
        float3 rw = float3(nmProj[0][3], nmProj[1][3], nmProj[2][3]);
        float3 d = cross(r0 - q.x * rw, r1 - q.y * rw);
        if (d.z < 0.0) d = -d;
        float3 c0 = nmView[0].xyz, c1 = nmView[1].xyz, c2 = nmView[2].xyz;
        float3 w = float3(dot(c0, d) / max(dot(c0, c0), 1e-8), dot(c1, d) / max(dot(c1, c1), 1e-8), dot(c2, d) / max(dot(c2, c2), 1e-8));
        return normalize(w);
    }
    float3 camPos() {
        float3 c0 = nmView[0].xyz, c1 = nmView[1].xyz, c2 = nmView[2].xyz;
        float3 t = nmView[3].xyz;
        return -float3(dot(c0, t) / max(dot(c0, c0), 1e-8), dot(c1, t) / max(dot(c1, c1), 1e-8), dot(c2, t) / max(dot(c2, c2), 1e-8));
    }
    bool setupModel() {
        float3 mx = nmModel[0].xyz, my = nmModel[1].xyz, mz = nmModel[2].xyz;
        float lx = length(mx), ly = length(my), lz = length(mz);
        float det = dot(mx, cross(my, mz));
        if (!(lx > 1e-6 && ly > 1e-6 && lz > 1e-6 && abs(det) > 1e-9 && abs(nmModel[3][3] - 1.0) < 0.01)) return false;
        MX = mx; MY = my; MZ = mz / lz * 0.5 * (lx + ly);
        MO = nmModel[3].xyz;
        float3 a = cross(MY, MZ), b = cross(MZ, MX), c = cross(MX, MY);
        float dt = dot(MX, a);
        if (abs(dt) < 1e-12) return false;
        MI = float3x3(float3(a.x, b.x, c.x), float3(a.y, b.y, c.y), float3(a.z, b.z, c.z)) / dt;
        return true;
    }
    float3 toScreen(float3 p) {
        float4 c = nmProj * (nmView * float4(p, 1.0));
        if (c.w <= 1e-6) return float3(0.0, 0.0, -1.0);
        float2 q = c.xy / c.w;
        float2 pix = q * GPS + screen.zw * 0.5;
        return float3(pix.x / screen.zw.x, 1.0 - pix.y / screen.zw.y, 1.0);
    }
    float4 scr(float2 uv) {
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        return amzTexture(0, uv);
    }
    float2 rot2(float2 v, float a) { float c = cos(a), s = sin(a); return float2(c * v.x - s * v.y, s * v.x + c * v.y); }
    void nmFxMain() {
        float4 orig = scr(amzScreenNorm());
        GPS = screen.zw.y / max(screen.zw.y, 1.0);
        float2 pix = float2(amzScreenNorm().x, 1.0 - amzScreenNorm().y) * screen.zw;
        float2 q = (pix - screen.zw * 0.5) / GPS;
        float B = floor(clamp(amzp_backLayers, 0.0, 60.0) + 0.5);
        float F = floor(clamp(amzp_frontLayers, 0.0, 60.0) + 0.5);
        float sg = max(amzp_startGap, 0.0);
        float stepD = int(amzp_spaceMode) == 1 ? max(amzp_layerGap, 0.0) : max(amzp_depth, 0.0) / max(max(B, F), 1.0);
        float extB = B > 0.5 ? sg + B * stepD : 0.0;
        float extF = F > 0.5 ? sg + F * stepD : 0.0;
        float dMin = -extF, dMax = extB;
        if (B + F < 0.5 || dMax - dMin < 1e-4) { amzOutput = (amzp_hideFace>0.5) ? float4(0.0) : orig; return; }
        SCN = int(amzp_camSrc) == 0 && camOK() > 0.5 && setupModel();
        float3 rl = float3(0.0), dl = float3(0.0, 0.0, 1.0);
        bool farUp = true;
        if (SCN) {
            float3 ro = camPos();
            float3 rd = rayDir(q);
            rl = MI * (ro - MO);
            dl = MI * rd;
            farUp = dot(MZ, MO - ro) >= 0.0;
        }
        float dNear = farUp ? dMin : dMax;
        float fa = radians(amzp_flatAngle);
        float2 fdir = float2(cos(fa), -sin(fa)) * amzp_flatLen * GPS / screen.zw;
        float4 cc = float4(0.5, 0.5, 0.0, 1.0) * amzLayerToScreen();
        float2 ctr = cc.xy;
        float2 asp = float2(screen.zw.x / max(screen.zw.y, 1.0), 1.0);
        float total = F + B + 1.0;
        float4 acc = float4(0.0);
        for (int i = 0; i < 121; i++) {
            float fi = float(i);
            if (fi >= total) break;
            float j = farUp ? fi - F : B - fi;
            bool face = abs(j) < 0.5;
            if (face && (amzp_hideFace>0.5)) continue;
            float d = face ? 0.0 : sign(j) * (sg + (abs(j) - 1.0) * stepD + stepD);
            float ext = d > 0.0 ? extB : extF;
            float g = face ? 0.0 : clamp(abs(d) / max(ext, 1e-4), 0.0, 1.0);
            float sc = max(mix(1.0, amzp_endScale, g), 1e-3);
            float tw = radians(amzp_twist) * g * sign(d + 1e-9);
            float2 off = amzp_endOff * g * sign(d + 1e-9);
            float4 c = float4(0.0);
            if (SCN) {
                if (abs(dl.z) < 1e-7) continue;
                float tt = (d - rl.z) / dl.z;
                if (tt <= 0.0) continue;
                float2 uv = rl.xy + tt * dl.xy;
                uv = rot2(uv - off, -tw) / sc;
                float3 sp = toScreen(MO + MX * uv.x + MY * uv.y);
                if (sp.z < 0.0) continue;
                c = face ? orig : scr(sp.xy);
            } else {
                float2 offU = off * GPS / screen.zw * float2(1.0, -1.0);
                float2 p = amzScreenNorm() - fdir * d - offU;
                float2 r = (p - ctr) * asp;
                r = rot2(r, tw) / sc;
                c = face ? orig : scr(ctr + r / asp);
            }
            if (c.a <= 0.0001) continue;
            float fs = clamp(abs(d - dNear) / max(dMax - dMin, 1e-4), 0.0, 1.0);
            if (!((amzp_keepFace>0.5) && face)) {
                float4 tc = mix(amzp_nearCol, amzp_farCol, fs);
                c.rgb = mix(c.rgb, tc.rgb * c.a, clamp(amzp_colorMix * tc.a, 0.0, 1.0));
                c.rgb *= 1.0 - clamp(amzp_sideShade, 0.0, 1.0) * fs;
                c *= mix(1.0, clamp(amzp_endOpacity, 0.0, 1.0), fs);
            }
            acc += c * (1.0 - acc.a);
            if (acc.a > 0.996) break;
        }
        amzOutput = acc;
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
